package org.dromara.sports.tables.d10.growth_profile;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import lombok.RequiredArgsConstructor;
import org.dromara.sports.api.GrowthFactApi;
import org.dromara.sports.platform.core.*;
import org.springframework.stereotype.Service;
import java.util.*;
import static org.dromara.sports.platform.core.BusinessSupport.*;

/** Points come exclusively from checked-in frozen rosters and current formally confirmed match results. */
@Service
@RequiredArgsConstructor
public class GrowthService implements GrowthFactApi,CapabilityProvider {
    private final ScopedJdbc db;
    private final ObjectMapper json;
    private final org.dromara.sports.api.GrowthPolicyApi policies;
    private static final Set<String> READS=Set.of("asp_account","asp_person","asp_team","asp_team_member","asp_sport","asp_profile_display","asp_growth_profile","asp_growth_record","asp_growth_policy","asp_title_equipment","asp_honor","asp_event","asp_competition_unit","asp_checkin","asp_registration","asp_registration_member","asp_roster_member","asp_roster_version","asp_match","asp_stage","asp_match_entry","asp_result_version","asp_result_item");
    private static final Set<String> WRITES=Set.of("asp_growth_profile","asp_growth_record","asp_growth_policy","asp_title_equipment","asp_honor");
    public List<CapabilityDefinition> capabilities(){return List.of(capability(json,"growth.card","查询本人或所在小队成长与荣誉","asp_growth_profile",true,false,Set.of("platform"),"",READS,Set.of(),"sportId","teamId?"),capability(json,"growth.equip","佩戴运动称号","asp_growth_profile",true,false,Set.of("platform"),"",READS,Set.of("asp_title_equipment"),"sportId","titleCode","teamId?","expectedVersion?"));}
    public JsonNode preview(String code,JsonNode input){return card(id(input,"sportId"),optionalId(input,"teamId"));}
    public JsonNode execute(String code,JsonNode input){
        if(code.equals("growth.card"))return preview(code,input);
        long account=account(),sport=id(input,"sportId");Long team=optionalId(input,"teamId");long owner=owner(account,team);String type=team==null?"person":"team",title=text(input,"titleCode",64);
        db.lock("equip:"+type+":"+owner+":"+sport);
        Map<String,Object> award=db.one("SELECT id FROM asp_honor WHERE "+(team==null?"person_id":"team_id")+"=? AND sport_id=? AND title_code=? AND status='verified' ORDER BY id DESC LIMIT 1",owner,sport,title);
        if(award==null)throw fail("请先获得这个称号；获得原因可在荣誉墙查看",409);
        var current=db.one("SELECT version FROM asp_title_equipment WHERE owner_type=? AND owner_id=? AND sport_id=?",type,owner,sport);
        if(current!=null&&input.has("expectedVersion")&&number(current.get("version"))!=input.get("expectedVersion").asLong())throw fail("佩戴状态已变化，请刷新后选择",409);
        db.update("INSERT INTO asp_title_equipment(id,owner_type,owner_id,sport_id,title_code,honor_id,frame_style) VALUES (?,?,?,?,?,?,'growth') ON CONFLICT(owner_type,owner_id,sport_id) DO UPDATE SET title_code=excluded.title_code,honor_id=excluded.honor_id,version=asp_title_equipment.version+1,update_time=CURRENT_TIMESTAMP",nextId(),type,owner,sport,title,award.get("id"));
        return reference(json,"ownerId",owner,"equipped");
    }
    private long person(long account){var p=db.one("SELECT person_id FROM asp_account WHERE id=? AND status='active'",account);if(p==null||p.get("person_id")==null)throw fail("补齐本人参赛资料后即可开启运动成长",409);return number(p.get("person_id"));}
    private long owner(long account,Long team){long person=person(account);if(team==null)return person;var t=db.one("SELECT id FROM asp_team WHERE id=? AND captain_person_id=? AND status='active'",team,person);if(t==null)throw fail("只有当前队长可以为小队佩戴称号",403);return team;}
    public JsonNode home(){long a=account();long p=person(a);return safeJson(json,db.list("SELECT gp.*,s.name AS sport_name FROM asp_growth_profile gp JOIN asp_sport s ON s.id=gp.sport_id WHERE (gp.owner_type='person' AND gp.owner_id=?) OR (gp.owner_type='team' AND gp.owner_id IN (SELECT team_id FROM asp_team_member WHERE person_id=? AND status='active')) ORDER BY gp.sport_id,gp.owner_type",p,p));}
    public JsonNode card(long sport,Long team){long account=account(),owner=ownerForView(account,team);String type=team==null?"person":"team";var row=db.one("SELECT * FROM asp_growth_profile WHERE owner_type=? AND owner_id=? AND sport_id=?",type,owner,sport);long points=row==null?0:number(row.get("points"));var rule=policies.current(sport);var result=json.createObjectNode();result.put("ownerId",Long.toString(owner));result.put("ownerType",type);result.put("sportId",Long.toString(sport));result.put("points",points);GrowthRankPresentation.apply(result,rule,points);result.set("titles",safeJson(json,db.list("SELECT id,title,title_code,awarded_at,source::text AS reason,status FROM asp_honor WHERE "+(team==null?"person_id":"team_id")+"=? AND sport_id=? AND title_code IS NOT NULL AND status='verified' ORDER BY awarded_at",owner,sport)));GrowthTitlePresentation.apply(result,rule,type,row==null?0:number(row.get("checkin_count")),row==null?0:number(row.get("finish_count")),result.path("titles"));result.set("equipment",safeJson(json,db.one("SELECT title_code,frame_style,version FROM asp_title_equipment WHERE owner_type=? AND owner_id=? AND sport_id=?",type,owner,sport)));result.set("facts",safeJson(json,db.list("SELECT id,event_id,milestone,points_delta,source::text AS source,create_time FROM asp_growth_record WHERE "+(team==null?"person_id":"team_id")+"=? AND sport_id=? AND source_key IS NOT NULL ORDER BY create_time DESC LIMIT 50",owner,sport)));return result;}
    private long ownerForView(long account,Long team){long p=person(account);if(team==null)return p;if(db.count("SELECT count(*) FROM asp_team_member WHERE team_id=? AND person_id=? AND status='active'",team,p)==0)throw fail("加入该队后可以查看队内成长",403);return team;}
    public JsonNode leaderboard(long team){ownerForView(account(),team);var result=safeJson(json,db.list("SELECT t.sport_id,a.id AS account_id,COALESCE(d.nickname,'球友') AS nickname,COALESCE(d.avatar_style,'mint') AS avatar_style,d.avatar_file_id,COALESCE(g.points,0) AS points,e.title_code FROM asp_team_member m JOIN asp_team t ON t.id=m.team_id JOIN asp_account a ON a.person_id=m.person_id LEFT JOIN asp_profile_display d ON d.account_id=a.id LEFT JOIN asp_growth_profile g ON g.owner_type='person' AND g.owner_id=m.person_id AND g.sport_id=t.sport_id LEFT JOIN asp_title_equipment e ON e.owner_type='person' AND e.owner_id=m.person_id AND e.sport_id=t.sport_id WHERE m.team_id=? AND m.status='active' ORDER BY points DESC,m.create_time",team));for(var member:result){var node=(com.fasterxml.jackson.databind.node.ObjectNode)member;var rule=policies.current(member.path("sport_id").asLong());int rank=rule.rank(member.path("points").asLong());node.put("rank_index",rank);node.put("rank_name",rule.rankNames().get(rank));}return result;}
    @Override
    @SportsAction(value="growth.reconcile",title="依据业务事实更新成长",reads={"asp_account","asp_person","asp_team","asp_team_member","asp_sport","asp_growth_profile","asp_growth_record","asp_growth_policy","asp_title_equipment","asp_honor","asp_event","asp_competition_unit","asp_checkin","asp_registration","asp_registration_member","asp_roster_member","asp_roster_version","asp_match","asp_stage","asp_match_entry","asp_result_version","asp_result_item"},writes={"asp_growth_profile","asp_growth_record","asp_growth_policy","asp_title_equipment","asp_honor"})
    public void reconcileEvent(Long event){
        db.lock("growth-event:"+event);var e=db.one("SELECT tenant_id FROM asp_event WHERE id=?",event);if(e==null)throw fail("赛事不存在",404);String tenant=e.get("tenant_id").toString();
        var desired=new LinkedHashMap<String,Fact>();
        for(var r:db.list("SELECT DISTINCT rm.person_id,u.sport_id FROM asp_checkin c JOIN asp_roster_member rm ON rm.person_id=c.person_id JOIN asp_roster_version rv ON rv.id=rm.roster_version_id JOIN asp_registration r ON r.id=rv.registration_id AND r.roster_revision=rv.revision JOIN asp_competition_unit u ON u.id=r.unit_id WHERE c.event_id=? AND u.event_id=? AND (c.unit_id IS NULL OR c.unit_id=u.id) AND c.status='confirmed' AND r.status='approved' AND rm.qualification_status='approved'",event,event)){long p=number(r.get("person_id")),s=number(r.get("sport_id"));desired.put("person:"+p+":"+s+":checkin",new Fact("person",p,s,"checkin",policies.forEvent(s,event).checkinPoints(),policies.forEvent(s,event).version()));}
        for(var r:db.list("SELECT DISTINCT rm.person_id,r.team_id,u.sport_id FROM asp_result_version v JOIN asp_result_item i ON i.result_version_id=v.id JOIN asp_match_entry me ON me.id=i.match_entry_id JOIN asp_registration r ON r.id=me.registration_id JOIN asp_competition_unit u ON u.id=r.unit_id JOIN asp_roster_member rm ON rm.roster_version_id=me.roster_version_id WHERE u.event_id=? AND v.status='confirmed' AND i.performance_status='valid' AND i.components->>'outcome' IN ('win','loss','draw') AND rm.qualification_status='approved'",event)){long p=number(r.get("person_id")),s=number(r.get("sport_id"));desired.put("person:"+p+":"+s+":finish",new Fact("person",p,s,"finish",policies.forEvent(s,event).finishPoints(),policies.forEvent(s,event).version()));if(r.get("team_id")!=null){long t=number(r.get("team_id"));desired.put("team:"+t+":"+s+":team_finish",new Fact("team",t,s,"team_finish",policies.forEvent(s,event).teamFinishPoints(),policies.forEvent(s,event).version()));}}
        var affected=new LinkedHashSet<Owner>();
        for(var row:db.list("SELECT * FROM asp_growth_record WHERE event_id=? AND source_key IS NOT NULL AND milestone<>'correction' AND status='effective' FOR UPDATE",event)){String type=row.get("person_id")==null?"team":"person";long owner=number(row.get(type.equals("person")?"person_id":"team_id")),s=number(row.get("sport_id"));String key=type+":"+owner+":"+s+":"+row.get("milestone");if(!desired.containsKey(key)){String correction="correction:"+row.get("id");db.update("INSERT INTO asp_growth_record(id,tenant_id,person_id,team_id,policy_version,achievement,source,status,sport_id,event_id,milestone,points_delta,source_key) VALUES (?,?,?,?,?,'{}'::jsonb,?::jsonb,'effective',?,?,'correction',?,?) ON CONFLICT (source_key) WHERE source_key IS NOT NULL DO NOTHING",nextId(),tenant,row.get("person_id"),row.get("team_id"),row.get("policy_version"),"{\"corrects\":\""+row.get("id")+"\"}",s,event,-number(row.get("points_delta")),correction);db.update("UPDATE asp_growth_record SET status='revoked',version=version+1,update_time=CURRENT_TIMESTAMP WHERE id=?",row.get("id"));affected.add(new Owner(type,owner,s));}}
        for(var entry:desired.entrySet()){Fact f=entry.getValue();String key="event:"+event+":"+entry.getKey();if(db.count("SELECT count(*) FROM asp_growth_record WHERE event_id=? AND sport_id=? AND "+(f.type.equals("person")?"person_id":"team_id")+"=? AND milestone=? AND status='effective'",event,f.sport,f.owner,f.milestone)==0){long generation=db.count("SELECT count(*) FROM asp_growth_record WHERE event_id=? AND sport_id=? AND "+(f.type.equals("person")?"person_id":"team_id")+"=? AND milestone=?",event,f.sport,f.owner,f.milestone);String finalKey=generation==0?key:key+":generation:"+generation;db.update("INSERT INTO asp_growth_record(id,tenant_id,person_id,team_id,policy_version,achievement,source,status,sport_id,event_id,milestone,points_delta,source_key) VALUES (?,?,?,?,?,'{}'::jsonb,?::jsonb,'effective',?,?,?,?,?) ON CONFLICT (source_key) WHERE source_key IS NOT NULL DO NOTHING",nextId(),tenant,f.type.equals("person")?f.owner:null,f.type.equals("team")?f.owner:null,f.policyVersion,"{\"eventId\":\""+event+"\",\"milestone\":\""+f.milestone+"\"}",f.sport,event,f.milestone,f.points,finalKey);}affected.add(new Owner(f.type,f.owner,f.sport));}
        for(Owner o:affected.stream().sorted(Comparator.comparing(Owner::type).thenComparingLong(Owner::id).thenComparingLong(Owner::sport)).toList())aggregate(o,tenant,event);
    }
    private void aggregate(Owner o,String tenant,long event){db.lock("growth-owner:"+o.type+":"+o.id+":"+o.sport);var rule=policies.current(o.sport);String column=o.type.equals("person")?"person_id":"team_id";var sums=db.one("SELECT COALESCE(sum(points_delta),0) AS points,count(*) FILTER(WHERE milestone='checkin' AND status='effective') AS checkins,count(*) FILTER(WHERE milestone IN ('finish','team_finish') AND status='effective') AS finishes FROM asp_growth_record WHERE "+column+"=? AND sport_id=? AND source_key IS NOT NULL",o.id,o.sport);long points=Math.max(0,number(sums.get("points"))),checks=number(sums.get("checkins")),finishes=number(sums.get("finishes"));db.update("INSERT INTO asp_growth_profile(id,owner_type,owner_id,sport_id,points,checkin_count,finish_count,policy_version) VALUES (?,?,?,?,?,?,?,?) ON CONFLICT(owner_type,owner_id,sport_id) DO UPDATE SET points=excluded.points,checkin_count=excluded.checkin_count,finish_count=excluded.finish_count,policy_version=excluded.policy_version,version=asp_growth_profile.version+1,update_time=CURRENT_TIMESTAMP",nextId(),o.type,o.id,o.sport,points,checks,finishes,rule.version());
        String[][] titles=o.type.equals("person")?new String[][]{{"first_checkin","首次登场",checks>=rule.personalTitles().get("first_checkin")?"1":"0"},{"first_finish","首次完赛",finishes>=rule.personalTitles().get("first_finish")?"1":"0"},{"regular","赛场常客",finishes>=rule.personalTitles().get("regular")?"1":"0"}}:new String[][]{{"team_first","默契初成",finishes>=rule.teamTitles().get("team_first")?"1":"0"},{"team_partners","默契搭档",finishes>=rule.teamTitles().get("team_partners")?"1":"0"},{"team_veterans","久经赛场",finishes>=rule.teamTitles().get("team_veterans")?"1":"0"}};
        for(String[] t:titles){db.update("UPDATE asp_honor SET status=?,update_time=CURRENT_TIMESTAMP,version=version+1 WHERE "+column+"=? AND sport_id=? AND title_code=?",t[2].equals("1")?"verified":"revoked",o.id,o.sport,t[0]);if(t[2].equals("1")&&db.count("SELECT count(*) FROM asp_honor WHERE "+column+"=? AND sport_id=? AND title_code=?",o.id,o.sport,t[0])==0)db.update("INSERT INTO asp_honor(id,tenant_id,event_id,person_id,team_id,category,title,source,status,awarded_at,sport_id,title_code) VALUES (?,?,?,?,?,'achievement',?,?::jsonb,'verified',CURRENT_TIMESTAMP,?,?)",nextId(),tenant,event,o.type.equals("person")?o.id:null,o.type.equals("team")?o.id:null,t[1],"{\"policy\":\""+rule.version()+"\",\"checkins\":"+checks+",\"finishes\":"+finishes+"}",o.sport,t[0]);}
        db.update("DELETE FROM asp_title_equipment WHERE owner_type=? AND owner_id=? AND sport_id=? AND honor_id IN (SELECT id FROM asp_honor WHERE status<>'verified')",o.type,o.id,o.sport);
    }
    private record Fact(String type,long owner,long sport,String milestone,int points,String policyVersion){}
    private record Owner(String type,long id,long sport){}
}
